-- GOVERNED MIGRATION-HISTORY RECOVERY.
-- This filename preserves a production ledger version for clean replay.
-- Production history is never rewritten; live hashes remain in the recovery manifest.
-- Semantic recovery of the provider-recorded SQL payload; comments and terminal newline may differ.

create or replace function public.projectos_get_context(p_organization_id uuid,p_project_key text,p_task_key text default null) returns jsonb language plpgsql security definer set search_path=public,private,auth,pg_temp as $$ declare v_project_id uuid;v_task jsonb;v_projection jsonb;v_product_key text;v_product_intelligence jsonb;begin if auth.role()<>'service_role' and not private.is_org_member(p_organization_id) then raise exception 'projectos_forbidden';end if;select id into strict v_project_id from public.projectos_projects where organization_id=p_organization_id and project_key=p_project_key;v_projection:=public.projectos_recompute_project(p_organization_id,p_project_key);if p_task_key is not null then select to_jsonb(task) into v_task from public.projectos_tasks task where task.project_id=v_project_id and task.task_key=p_task_key;end if;v_product_key:=private.projectos_canonical_product_key(p_project_key);if v_product_key is not null then v_product_intelligence:=public.projectos_get_product_intelligence_context(p_organization_id,v_product_key,30);end if;return jsonb_build_object('projection',v_projection,'task',v_task,'projectLessons',coalesce((select jsonb_agg(to_jsonb(lesson) order by lesson.confidence desc,lesson.evidence_count desc) from public.projectos_lessons lesson where lesson.organization_id=p_organization_id and lesson.project_id=v_project_id and lesson.status in('candidate','promoted')),'[]'::jsonb),'portfolioLessons',coalesce((select jsonb_agg(to_jsonb(lesson) order by lesson.confidence desc,lesson.evidence_count desc) from public.projectos_lessons lesson where lesson.organization_id=p_organization_id and lesson.scope in('portfolio','operational') and lesson.status='promoted'),'[]'::jsonb),'builderRecommendations',public.projectos_recommend_agents(p_organization_id,p_project_key,'builder',5),'reviewerRecommendations',public.projectos_recommend_agents(p_organization_id,p_project_key,'reviewer',5),'productIntelligence',v_product_intelligence);end;$$;
